import sys
import requests
import json
import re
from decimal import Decimal, getcontext

def format_number(value):
    if isinstance(value, float):
        if value.is_integer():
            return int(value)
        else:
            return f"{value:.6f}".rstrip('0').rstrip('.') if '.' in f"{value:.6f}" else f"{value:.6f}"
    return str(value)

def render_template(template_path, json_data):
    try:
        with open(template_path, 'r') as f:
            template = f.read()
    except IOError:
        print("Error: Could not read template file", file=sys.stderr)
        sys.exit(1)

    for key, value in json_data.items():
        json_data[key] = format_number(value)

    def replace_match(match):
        expr = match.group(1)
        try:
            result = eval(expr, {}, json_data)
            return format_number(result)
        except:
            return match.group(0)

    rendered = re.sub(r'\{\{([^}]+)\}\}', replace_match, template)
    return rendered

def main():
    if len(sys.argv) != 3:
        print("Error: Usage: python report_renderer.py <url> <template_path>", file=sys.stderr)
        sys.exit(1)

