import sys
import requests
import re
from urllib.parse import urlparse

def fetch_json(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        print(f"Error fetching URL: {e}", file=sys.stderr)
        sys.exit(1)

def evaluate_expression(expr, data):
    try:
        # Replace JSON keys with their values in the expression
        for key, value in data.items():
            expr = expr.replace(key, str(value))
        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        print(f"Error evaluating expression: {e}", file=sys.stderr)
        sys.exit(1)

def render_template(template_path, data):
    try:
        with open(template_path, 'r') as file:
            template = file.read()
        # Replace all placeholders with evaluated expressions
        pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
        def replacer(match):
            expr = match.group(1)
            return evaluate_expression(expr, data)
        rendered = pattern.sub(replacer, template)
        return rendered
    except Exception as e:
        print(f"Error reading template file: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report_renderer.py <url> <template_path>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    template_path = sys.argv[2]

    data = fetch_json(url)
    rendered_html = render_template(template_path, data)
    print(rendered_html)

if __name__ == "__main__":
    main()
